mapper.select:
SELECT s.id, s.nombre, s.direccion_id, s.telefono, s.email, s.horario_apertura, s.horario_cierre, s.latitud, s.longitud, s.activa, s.created_at, s.updated_at, s.deleted, s.version FROM sucursal s
s.deleted = FALSE AND s.nombre ILIKE '%' || #{nombre} '%'
ORDER BY s.created_at DESC LIMIT #{limit} OFFSET #{offset}
